#include <stdio.h>
typedef struct N { int v; struct N *l, *r; } N;
int main(void) {
    N x = {40, 0, 0}, e = {70, 0, 0};
    N b = {20, 0, &x}, c = {60, 0, &e};
    N a = {50, &b, &c};
    N *cur = &a;
    while (cur->v != 40)
        cur = (40 < cur->v) ? cur->l : cur->r;
    printf("%d\n", cur->v);
    return 0;
}

#include <stdio.h>
typedef struct N { int v; struct N *l, *r; } N; N pool[8]; int used;
N *ins(N *t, int k) {
    if (!t) { N *n = &pool[used++]; n->v = k; n->l = n->r = 0; return n; }
    if (k < t->v) t->l = ins(t->l, k); else t->r = ins(t->r, k);
    return t;
}
int main(void) {
    N *t = 0; int ks[] = {50, 30, 70, 20};
    for (int i = 0; i < 4; i++) t = ins(t, ks[i]);
    printf("%d\n", t->l->l->v);
    return 0;
}

#include <stdio.h>
typedef struct N { int v; struct N *l, *r; } N;
int ok(N *n, int lo, int hi) {
    if (!n) return 1;
    if (n->v <= lo || n->v >= hi) return 0;
    return ok(n->l, lo, n->v) && ok(n->r, n->v, hi);
}
int main(void) {
    N b = {20, 0, 0}, c = {60, 0, 0};
    N a = {50, &b, &c};
    printf("%d\n", ok(&a, -1000000, 1000000));
    return 0;
}

#include <stdio.h>
int h[8] = {3, 7, 9, 12};
int n = 4;
int main(void) {
    int v = 4;
    h[n] = v; int i = n++;
    while (i > 0 && h[(i - 1) / 2] > h[i]) {
        int t = h[i]; h[i] = h[(i - 1) / 2]; h[(i - 1) / 2] = t;
        i = (i - 1) / 2;
    }
    printf("%d %d %d %d %d\n", h[0], h[1], h[2], h[3], h[4]);
    return 0;
}

#include <stdio.h>
typedef struct N { int v; struct N *l, *r; } N; int target = 3, got = -1, cnt = 0;
void rev(N *n) {
    if (!n || got != -1) return;
    rev(n->r);
    if (++cnt == target) { got = n->v; return; }
    rev(n->l);
}
int main(void) {
    N a = {20, 0, 0}, b = {40, 0, 0}, c = {10, &a, 0}, d = {30, &c, &b};
    rev(&d); printf("%d\n", got);
    return 0;
}
